:root {
  --bg: #fff;
  --fg: #111;
  --muted: #666;
  --accent: #0b79ff;
  --gap: 1rem;
}

header {
  display: flex;
  justify-content: space-between;
  padding: var(--gap);
  background: var(--bg);
  color: var(--fg);
}

nav ul {
  display: flex;
  gap: var(--gap);
  list-style: none;
}

.dropdown {
  position: relative;
}

.dropdown-menu {
  position: absolute;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-10px);
  transition: opacity 0.3s, transform 0.3s, visibility 0.3s;
}

.dropdown:hover .dropdown-menu,
.dropdown:focus-within .dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

@media (max-width: 768px) {
  nav ul {
    flex-direction: column;
  }
}
```

